  const movement=await page.evaluate(()=>{const refs=[...document.querySelectorAll('.cover-number[data-token]')],pick=id=>{const el=document.querySelector('[data-token="'+id+'"]'),r=el.getBoundingClientRect();return{x:r.x+r.width/2,y:r.y+r.height/2,opacity:Number(getComputedStyle(el).opacity)};},scan=(a,b)=>{const out=[];for(let time=a;time<=b;time+=20){NMCoverMath.seek(time);out.push({time,two:pick('two'),five:pick('five'),eight:pick('eight')});}return out;};return{split:scan(1600,2500),gather:scan(4000,5000),width:document.querySelector('.cover-equation').clientWidth,sameNodes:refs.every((r,i)=>r===document.querySelectorAll('.cover-number[data-token]')[i])};});assert(movement.sameNodes,'Regrouping must move the same digit nodes');assert(movement.split.at(-1).two.x<movement.split[0].two.x-movement.width*.2,'Seven visibly separates into two on the left');assert(movement.split.at(-1).five.x>movement.split[0].five.x+movement.width*.1,'The remaining five separates to the right');assert(movement.gather[0].two.x-movement.gather.at(-1).two.x>movement.width*.2,'Two must visibly travel toward eight');assert(Math.abs(movement.gather.at(-1).two.x-movement.gather.at(-1).eight.x)<1,'Eight and two meet before becoming ten');let largestStep=0;for(let i=1;i<movement.gather.length;i++){const a=movement.gather[i-1].two,b=movement.gather[i].two;assert(b.x<=a.x+.1,'Two moves left continuously');largestStep=Math.max(largestStep,Math.hypot(b.x-a.x,b.y-a.y));}assert(largestStep<movement.width*.025,'Moving two must not teleport between completed formulas');assert(movement.gather.filter(f=>f.time<=4800).every(f=>f.two.opacity>.5),'The traveling digit remains visible until it merges');
  const particles=await page.evaluate(()=>{const ctx=document.querySelector('#coverMath canvas').getContext('2d'),original=ctx.arc,record=time=>{const calls=[];ctx.arc=function(x,y,r,...rest){calls.push({x,y,r});return original.call(this,x,y,r,...rest);};try{NMCoverMath.seek(time);}finally{ctx.arc=original;}return{travel:calls.filter(c=>Math.abs(c.r-2.1)<1e-6),total:calls.length};};return{before:record(3900),early:record(4200),late:record(4800),after:record(5100),burst:record(8100),finished:record(9100)};});
  assert.equal(particles.before.travel.length,0);assert.equal(particles.early.travel.length,2,'Exactly two source stars move from seven to eight');assert.equal(particles.late.travel.length,2);assert(particles.early.travel.reduce((s,p)=>s+p.x,0)>particles.late.travel.reduce((s,p)=>s+p.x,0),'The two gold stars move left from seven toward eight');assert.equal(particles.after.travel.length,0);assert.equal(particles.finished.total,140,'Keep the original 140-star background');assert.equal(particles.burst.total-particles.finished.total,44,'Original completion burst contains 44 particles');
  const loop=await page.evaluate(()=>{const stateAt=time=>{NMCoverMath.seek(time);return[...document.querySelectorAll('.cover-number[data-token]')].map(e=>({opacity:getComputedStyle(e).opacity,transform:getComputedStyle(e).transform}));};return{early:stateAt(100),repeated:stateAt(9700),duration:NMCoverMath.getState().loop};});assert.equal(loop.duration,9600);assert.deepEqual(loop.repeated,loop.early,'Four readable beats repeat on the 9600ms loop');
  await page.evaluate(()=>NMCoverMath.seek(0));await page.waitForFunction(()=>NMCoverMath.getState().step==='1',null,{timeout:4000});
  // Visibility is emulated at the platform boundary, rather than calling the
