    const video=document.querySelector('#introVideo'),box=video.getBoundingClientRect(),paper=document.querySelector('#bookContent').getBoundingClientRect(),bar=document.querySelector('.cinema-controls'),controls=bar.getBoundingClientRect(),style=getComputedStyle(video),scale=Math.min(box.width/video.videoWidth,box.height/video.videoHeight),width=video.videoWidth*scale,height=video.videoHeight*scale;
